INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (86, 245, 'BOPP Metallized Film silver', '../upload/image/20180929/20180929100620_45444.jpg', '<p></p><div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <table arial="" border="0" cellpadding="0" cellspacing="5" class="ke-zeroborder" geneva="" helvetica="" new="" roman="" sans-serif="" style="width: 700px; color: rgb(58, 58, 58); font-family:;" times="" verdana="" width="95%"> <tbody> <tr> <td style="background-color:transparent;"> <div align="center"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>BOPP Metallized Film</strong></span> </div> </td> </tr> <tr> <td style="background-color:transparent;"> <div align="left"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Useage: used as vacuum metallization, radiation, anti-counterfeiting of the substrate, food packaging.</span> </div> <div align="left"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Featuring: Excellent sealing strength , excellent adhesion and metal gloss , excellent printing ink no effect.</span> </div> <div align="left"> <span style="color:black;font-size:12pt;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">Color: Silver (coated with AL.)</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Thickness: 20,25,30,40,45 UM (Microns)</span></span> </div> <div align="left"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">(Thickness tolerance: ± 3% β-ray thickness measurement)</span> </div> <div align="left"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">Applications: Used for packing .</span> </div> </td> </tr> </tbody> </table> <div arial="" geneva="" helvetica="" new="" roman="" sans-serif="" style="color: rgb(58, 58, 58); font-family:;" times="" verdana=""> </div> <table arial="" border="0" cellpadding="0" cellspacing="5" class=