INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (86, 253, 'Zinc/aluminium alloy metallised Capacitor PP-film', '../upload/image/20181227/20181227140337_23318.jpg', '<p><span style="color:#3A3A3A;font-family:Tahoma;font-size:18px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">Metallized BOPP Capacitor Film (sliver)</span></p><div style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> </div> <p style=''color:#3A3A3A;text-indent:0px;font-family:"font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;''> <span style="font-size:16px;"><span style="font-family:Tahoma;font-size:18px;">Metallized BOPP Capacitor Film (sliver film) have two items :</span><br/> <span style="font-family:Tahoma;font-size:18px;">1. Zn/Al Metallized BOPP Capacitor Film (sliver film)</span><br/> <span style="font-family:Tahoma;font-size:18px;">2. Al Metallized BOPP Capacitor Film (sliver film)</span><br/> <span style="font-family:Tahoma;font-size:18px;">reinforced edge ( of Aluminum/Zinc film ) are : 1.5,2.0,2.5 MM</span><br/> <span style="font-family:Tahoma;font-size:18px;">The standard thickness range including: 3,4,5,6,7,8,9,10,12 microns .</span><br/> <span style="font-family:Tahoma;font-size:18px;">The standard tolerance thickness: +/-0.2 Um .</span><br/> <span style="font-family:Tahoma;font-size:18px;">The standard width range including: 30,40,50,60,70,80,90,100,120,130 MM</span><br/> <span style="font-family:Tahoma;font-size:18px;">The standard tolerance width: +/-5 MM.</span><br/> <span style="font-family:Tahoma;font-size:18px;">The inner core : 3" (76MM)</span><br/> <span style="font-family:Tahoma;font-size:18px;">The outer core: 150-350 MM .</span><br/> <span style="font-family:Tahoma;font-size:18px;">Features:</span><br/> <span style="font-family:Tahoma;font-size:18px;">1) single side corona treated for the Zn or Zn/Al metallized .</span><br/> <br/> <br/> </span></p> <table border="1" cellpadding="0" cellspacing="0" style=''color:#3A3A3A;font-family:"font-size:12px;font-style:normal;font-weight:normal;border-collapse:collapse;background-color:#FFFFFF;''> <tbody> <tr> <td colspan="2" style="border:1pt solid black;background-color:transparent;" valign="top" width="638"> <div> </div> <div> <span style="font-size:16px;"><span><span style="font-family:Tahoma;font-size:18px;">Tech data :</span><br/> <br/> <span style="font-family:Tahoma;font-size:18px;">Zinc/aluminium alloy metallised PP-film with heavy edge and improved corrosion stability. Base film is produced with super clean electrical grade resin.</span></span></span> </div> <div> </div> <span style="font-size:16px;"> <div> <span style="font-family:Tahoma;font-size:18px;">GENERAL APPLICATIONS ( VMPP film)</span> </div> </span> <div> </div> <div> <span style="font-family:Tahoma;font-size:18px;"><span style="font-family:Tahoma;font-size:18px;">AC low voltage power capacitors with highest stresses and largest units. Suitable also for motor run and lighting capacitors.</span></span> </div> <div> </div> </td> </tr> <tr> <td style="background-color:transparent;" valign="top" width="319"> <div> <span style="font-family:Tahoma;font-size:18px;">Properties</span> </div> </td> </tr> </tbody> </table>', '2026-09-06 20:58:45');